const now = new Date();
const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const todayName = dayNames[now.getDay()];

// Schedules match config/schedules.yaml (Mon/Wed/Fri/Sun = poster, Tue/Thu/Sat = reel)
const scheduleMap = {
  'Monday': { type: 'poster', slot: 'poster-1', pillar: 'Computer Science Concepts', topic: 'What Is an API?' },
  'Tuesday': { type: 'reel', slot: 'reel-1', pillar: 'Python and Automation', topic: 'Python List vs Tuple' },
  'Wednesday': { type: 'poster', slot: 'poster-2', pillar: 'AI Tools and Practical AI', topic: 'What Is an AI Hallucination?' },
  'Thursday': { type: 'reel', slot: 'reel-2', pillar: 'Web Development Basics', topic: 'How Does DNS Work?' },
  'Friday': { type: 'poster', slot: 'poster-3', pillar: 'Open Source and Linux', topic: 'Top 5 Git Commands' },
  'Saturday': { type: 'reel', slot: 'reel-3', pillar: 'Python and Automation', topic: 'How to Read a JSON File in Python' },
  'Sunday': { type: 'poster', slot: 'poster-4', pillar: 'Computer Science Concepts', topic: 'Stack vs Queue Simply Explained' }
};

const slotInfo = scheduleMap[todayName] || scheduleMap['Monday'];
const timestamp = now.toISOString().slice(0, 10).replace(/-/g, '');
const idempotencyKey = `scheduled-${slotInfo.slot}-${timestamp}`;

return [{
  json: {
    day: todayName,
    content_type: slotInfo.type,
    slot: slotInfo.slot,
    pillar: slotInfo.pillar,
    topic: slotInfo.topic,
    idempotency_key: idempotencyKey
  }
}];

